import useGetApiData from '@/hooks/pro/useGetApiData'
import useProHelper from '@/hooks/pro/useProHelper'
import useProListStore from '@/store/pro/list'
import { CetusTooltip } from '@cetus/design'
import SingleTokenInfo from '@cetus/design/src/components/common/SingleTokenInfo'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { Icon } from '@cetus/ui-kit'
import { Box, Center, HStack, Image, Text } from '@chakra-ui/react'
import { keyframes } from '@emotion/react'
import { useEffect, useRef, useState } from 'react'

// 从右向左滚动
const scroll = keyframes`
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
`
const tabs = [
  { iconSel: '/images/icon_watchlist_sel@2x.png', iconNor: '/images/icon_watchlist_nor@2x.png', label: 'Watchlist' },
  { iconSel: '/images/icon_trending_sel@2x.png', iconNor: '/images/icon_trending_nor@2x.png', label: 'Trending' }
]
const limit = 15
const trendingParams = {
  sorted_by: 'rank',
  date_type: 'hour24',
  desc: true,
  limit: 20,
  offset: 0,
  market_cap_max: '',
  market_cap_min: '',
  volume_max: '',
  volume_min: '',
  liqidity_max: '',
  liqidity_min: '',
  text: '',
  tag: 'trending'
}

export default function CarouselBlock({ containerProps }: { containerProps?: any }) {
  const { getProCoinList, getProCoinListWithCoins } = useGetApiData()
  const { userCollectObj } = useTokenSelectStore()
  const { quickCoin, currentCarouselTab, setCurrentCarouselTab, setProListParams, setCurrentProTab } = useProListStore()
  const [data, setData] = useState<any>()
  const { goToken } = useProHelper()
  const { isApp, windowWidth } = useWindowWidth()

  // 获取除了收藏以外的tab的列表
  const fetchProData = async () => {
    try {
      const res = await getProCoinList({ ...trendingParams, limit })
      console.log('🚀 ~ fetchProData ~ res.list:', res.list)
      setData(res.list)
    } catch (err) {
      console.log('🚀 ~ fetchProData ~ err:', err)
    }
  }

  // 获取除了收藏列表
  const fetchWatchList = async () => {
    const coins = Object.keys(userCollectObj || {})
    const res = await getProCoinListWithCoins(coins, trendingParams?.date_type, '')
    console.log('🚀 ~ fetchWatchList ~ res:', res)
    setData(res)
  }

  const trackRef = useRef<HTMLDivElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  const [shouldScroll, setShouldScroll] = useState(false)
  const [animationDuration, setAnimationDuration] = useState('30s')

  const previousTab = useRef(currentCarouselTab)
  const previousWindowWidth = useRef(windowWidth)
  const [hasMounted, setHasMounted] = useState(false)
  useEffect(() => {
    if (currentCarouselTab === 'Trending') {
      if (previousTab.current !== currentCarouselTab || !hasMounted || previousWindowWidth.current !== windowWidth) {
        setData([])
        setShouldScroll(false)
        fetchProData()
      }
    } else {
      setData([])
      setShouldScroll(false)
      fetchWatchList()
    }
    setHasMounted(true)

    // 更新 previous 的值
    previousTab.current = currentCarouselTab
    previousWindowWidth.current = windowWidth
  }, [hasMounted, currentCarouselTab, userCollectObj, windowWidth])

  useEffect(() => {
    if (!trackRef.current || !containerRef.current) return

    const trackWidth = trackRef.current.offsetWidth
    const containerWidth = containerRef.current.offsetWidth

    if (trackWidth <= containerWidth) {
      setShouldScroll(false)
    } else {
      setShouldScroll(true)
      const speed = 80 // px per second
      const duration = trackWidth / speed
      setAnimationDuration(`${duration}s`)
    }
  }, [data]) // 数据变化时重新计算

  const handleRefresh = () => {
    if (currentCarouselTab == 'Trending') {
      fetchProData()
    } else {
      fetchWatchList()
    }
  }
  // 1分钟自动刷新
  useEffect(() => {
    const intervalId = setInterval(() => {
      handleRefresh()
    }, 60 * 1000)
    return () => clearInterval(intervalId)
  }, [])
  return (
    <HStack
      w="100%"
      justify="flex-end"
      h="58px"
      position="sticky"
      top="80px"
      bg="bg_primary"
      zIndex="999"
      mb={{ base: '4px', lg: '0' }}
      pl={{ base: '12px', lg: '20px' }}
      {...containerProps}
    >
      <HStack
        w={{ base: '88px', lg: '146px' }}
        flexDirection={{ base: 'column', lg: 'row' }}
        align={{ base: 'flex-start', lg: 'center' }}
        gap={{ base: '2px', lg: '8px' }}
      >
        <HStack w="52px" gap="0" h="28px" p="2px" borderRadius="8px" border="1px solid" borderColor="border" bg="bg_secondary">
          {tabs.map(tab => (
            <Center
              key={tab.label}
              cursor="pointer"
              onClick={() => setCurrentCarouselTab(tab.label as 'Watchlist' | 'Trending')}
              h="100%"
              w="50%"
              bg={currentCarouselTab === tab.label ? 'primary_opacity.10' : 'none'}
              borderRadius="6px"
            >
              <Image src={currentCarouselTab === tab.label ? tab.iconSel : tab.iconNor} w="16px" h="16px" />
            </Center>
          ))}
        </HStack>

        <CetusTooltip
          showTooltip={isApp || currentCarouselTab == 'Watchlist' ? false : true}
          placement="top"
          tooltip={<Text fontSize="12px">Tokens trending over the past 24h.</Text>}
        >
          <HStack>
            <Text
              color="text_caption"
              w="62px"
              cursor="pointer"
              ml={{ base: '0', lg: '4px' }}
              mr="-4px"
              onClick={() => {
                setCurrentProTab(currentCarouselTab)
                if (currentCarouselTab == 'Trending') {
                  setProListParams(trendingParams)
                }
              }}
            >
              {currentCarouselTab}
            </Text>
            <Icon xlinkHref="#icon-detail" svgW="12px" svgH="12px" ml="-4px" />
          </HStack>
        </CetusTooltip>
      </HStack>
      <Box
        overflow="hidden"
        ref={containerRef}
        whiteSpace="nowrap"
        width={{ base: 'calc(100% - 88px)', lg: 'calc(100% - 146px)' }}
        position="relative"
        p="9px 0"
        _hover={{
          '& > .carousel-track': {
            animationPlayState: 'paused'
          }
        }}
      >
        {data && data?.length > 0 && (
          <HStack
            className="carousel-track"
            // minW="200%" // 确保重复内容后滚动 50% 正好轮一遍
            gap="12px"
            ref={trackRef}
            animation={shouldScroll ? `${scroll} ${animationDuration} linear infinite` : 'none'}
            willChange="transform"
            minW="fit-content"
          >
            {[...data, ...(shouldScroll ? data : [])]?.map((item: any, index: number) => (
              <HStack
                key={`${item?.coin_type}-${index}`}
                h="40px"
                borderRadius="8px"
                bg="card_bg"
                cursor="pointer"
                p="0 8px"
                gap="4px"
                _hover={{ bg: '#2B3742' }}
                onClick={() => goToken(quickCoin?.coin_type, item?.coin_type)}
              >
                <Text fontSize="12px" color="text_caption">
                  #{(index % data?.length) + 1}
                </Text>
                <SingleTokenInfo
                  warningIcon={{ iconW: '12px', iconH: '12px' }}
                  token={item}
                  haveName={false}
                  imgBoxStyle={{ w: '20px', h: '20px' }}
                />
                <Text fontSize="12px" color="text_caption" ml="12px">
                  {item?.price}
                </Text>
                <Text
                  fontSize="12px"
                  color={
                    item?.priceChange == '--' || Number(item?.priceChange) === 0
                      ? 'text_caption'
                      : item?.priceChange?.includes('-')
                        ? 'primary_red'
                        : 'primary_green'
                  }
                >
                  {item?.priceChange}
                </Text>
              </HStack>
            ))}
          </HStack>
        )}
        {/* 左侧渐变遮罩 */}
        {shouldScroll && (
          <Box
            position="absolute"
            left="0"
            top="0"
            bottom="0"
            w={{ base: '28px', lg: '60px' }}
            pointerEvents="none"
            bgGradient="linear(to-r, #161616, transparent)"
          />
        )}
      </Box>
    </HStack>
  )
}
